const tickets = $input.first().json.results || [];
let total = tickets.length;
let missingToken = 0;
let rfqCount = 0;

for (const t of tickets) {
  const fields = t.custom_fields || [];
  const tokenField = fields.find(f => f.id === 'hc_session_token' || f.id === 'session_token' || f.id === 17953452223503 || f.id === '17953452223503');
  if (!tokenField || !tokenField.value) {
    missingToken++;
  }
  if ((t.tags || []).includes('rfq_detected')) {
    rfqCount++;
  }
}

const missingPct = total > 0 ? ((missingToken / total) * 100).toFixed(1) : '0.0';

return [{
  json: {
    date: new Date().toLocaleDateString('en-PH', { timeZone: 'Asia/Manila' }),
    total_tickets: total,
    missing_token: missingToken,
    missing_pct: missingPct,
    rfq_count: rfqCount,
    status: (parseFloat(missingPct) > 20) ? 'ATTENTION_NEEDED' : 'HEALTHY'
  }
}];

